];

function ReviewDetail() {
  const { id } = useParams();
  const [review, setReview] = useState(null);
  const [loading, setLoading] = useState(true);
  const [trails, setTrails] = useState([]);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const containerRef = useRef(null);
  const trailIdRef = useRef(0);

  // 마우스 추적 + 브러쉬 트레일 효과
  useEffect(() => {
    const handleMouseMove = (e) => {
      if (containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        setMousePos({
          x: ((e.clientX - rect.left) / rect.width) * 100,
          y: ((e.clientY - rect.top) / rect.height) * 100
        });
        
        // 파스텔 노란색 브러쉬 트레일
        const newTrail = {
          id: trailIdRef.current++,
          x: e.clientX,
          y: e.clientY,
          size: Math.random() * 30 + 18,
          color: ['#ffeb3b', '#ffc107', '#ffb74d', '#ffd54f', '#ffe082', '#fff176', '#ff9800', '#ffcc80'][Math.floor(Math.random() * 8)],
          opacity: 0.95
        };
        setTrails(prev => [...prev.slice(-20), newTrail]);
      }
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  // 트레일 페이드아웃
  useEffect(() => {
    if (trails.length === 0) return;
    const timer = setInterval(() => {
      setTrails(prev => prev.filter(t => Date.now() - t.id < 680).map(t => ({
        ...t,
        opacity: Math.max(0, t.opacity - 0.055),
        size: t.size * 0.94
      })));
    }, 45);
    return () => clearInterval(timer);
  }, [trails.length]);

  useEffect(() => {
    const load = async () => {
      // 먼저 샘플 리뷰에서 찾기
      const sampleReview = sampleReviews.find(r => r._id === id);
      if (sampleReview) {
        setReview(sampleReview);
        setLoading(false);
        return;
      }
      
      // 샘플에 없으면 API에서 가져오기
      try {
        const res = await fetchReview(id);
        setReview(res.data);
      } catch (err) {
        console.error('fetch review', err);
      } finally {
        setLoading(false);
      }
    };
    if (id) load();
  }, [id]);

  if (loading) return <div style={{ padding: 20 }}>로딩중...</div>;
  if (!review) return <div style={{ padding: 20 }}>리뷰를 찾을 수 없습니다.</div>;

  return (
    <div 
      ref={containerRef}
      style={{ 
        padding: 20, 
        maxWidth: 900, 
        margin: '0 auto', 
        minHeight: '100vh',
        background: `
          radial-gradient(circle at ${mousePos.x}% ${mousePos.y}%, rgba(255,77,136,0.08) 0%, transparent 50%),
          linear-gradient(180deg, #fff 0%, #fff5f7 50%, #faf5ff 100%)
        `,
        position: 'relative'
      }}
    >
      {/* 🎨 파스텔 노란색 브러쉬 트레일 */}
      {trails.map((trail) => (
        <div
          key={trail.id}
          style={{
            position: 'fixed',
            left: trail.x,
            top: trail.y,
            width: trail.size,
            height: trail.size,
            borderRadius: '50%',
            background: `radial-gradient(circle, ${trail.color} 0%, ${trail.color}cc 30%, ${trail.color}66 60%, transparent 80%)`,
            opacity: trail.opacity,
            pointerEvents: 'none',
            zIndex: 9999,
            filter: 'blur(2px)',
            boxShadow: `0 0 ${trail.size * 1.5}px ${trail.color}, 0 0 ${trail.size * 0.8}px ${trail.color}`,
            transform: 'translate(-50%, -50%)'
          }}
        />
      ))}

      <h1>{review.title}</h1>
      <div style={{ color: '#666' }}>작성자: {review.author?.username || '익명'}</div>
      <div style={{ marginTop: 12, lineHeight: 1.7 }}>{review.text}</div>

      {review.images && review.images.length > 0 && (
        <div style={{ display: 'flex', gap: 8, marginTop: 12 }}>
          {review.images.map((src, i) => (
            <img key={i} src={src} alt={`img-${i}`} style={{ width: 240, height: 240, objectFit: 'cover', borderRadius: 8 }} />
          ))}
        </div>
      )}
    </div>
  );
}

export default ReviewDetail;
